$(function() {
    $("div.navbar-header div.visible-xs").removeClass("btn-group"); 

	var yuleDec15 = new Date(2021, 11, 15);
	if (new Date() < yuleDec15) 
	{ 
        $("#main-content").prepend('<div style="font-size: 20px;text-align: center;margin: 0 0 10px 0;" class="alert alert-success" id="yuletideban"><a href="https://www.hofstra.edu/yuletide2021" target="_blank" rel="noopener"><span class="fa fa-snowflake-o"></span> Support the Yuletide Scholarship Fundraiser <span class="fa fa-snowflake-o"></span></a></div>');
    }
});
$(function() {
    $("div.navbar-header div.visible-xs").removeClass("btn-group"); 

	var nssePromptStart = new Date(2022, 2, 2); //March 2, 2022
    var nssePromptStop = new Date(2022, 2, 31, 23, 59, 59); //March 31, 2022
	if (new Date() > nssePromptStart && new Date() < nssePromptStop) 
	{ 
        // check if user is Student and either Freshman or Senior
        var user = hof.lum.Luminis.getUser();
        if(user){
            user.addEventListener(hof.lum.event.EventType.LOAD, function(){
                if (user.getRoles().indexOf("STUDENT") > -1 ) {
//                    console.log("Student login between correct dates: studentClass = " + user.getStudentClass().getCode());
                    $.ajax({
                        method: 'GET',
                        url: '/hofapps/applications/nsse/getSurveyLink.jsp',
                        success: function(result) {
                            var studentURL = result.url;
//                            console.log("url = " + studentURL);
//                            console.log("studentURL != null && studentURL.length !== 0 : " + (studentURL != null && studentURL.length !== 0));
                            if (studentURL != null && studentURL.length !== 0) {
//                                console.log("display banner");
                                $("#main-content").prepend('<div style="font-size: 20px;text-align: center;margin: 0 0 10px 0;" class="alert alert-info" id="nsseSurvey"><a href="' + result.url + '"  target="_blank" rel="noopener"><span class="fa fa-calendar-check-o"></span> Please help Hofstra by completing the National Survey of Student Engagement (NSSE) </a></div>');
                            }
                        },
                        error: function(jqXHR, textStatus, errorThrown) {
                            console.log(JSON.stringify(jqXHR));
                            console.log("AJAX error: " + textStatus + ' : ' + errorThrown);
                        }
                    });
                } else {
//                    console.log("User is not a Student");
                }
            });
        }
    } else {
//        console.log("Student login is not between correct dates");
    }
});